assign si5340a_controller_start = ~BUTTON[0];
wire si5340a_ready;
// 運作原理
// 用來「設定」外部那顆實體的 Silicon Labs Si5340A 時脈產生器晶片
// SI5340A 會產生 644.53125 MHz
// 這個 CLK = QSFPA_REFCLK_p 這個 port 進來, 之後要給 ATX PLL 當作參考時脈
si5340a_controller si5340a_controller(
                       .iCLK(CLK_50_B2J),
                       .iRST_n(CPU_RESET_n),
                       .iStart(si5340a_controller_start),
                       .iPLL_OUT0_FREQ_SEL(`SI5340A_644M53125),//QSFP-A
