wire tx_cal_busy_w, rx_cal_busy_w;
wire tx_ready_w, rx_ready_w;
wire rx_is_lockedtodata_w;
PHY_RST PHY_RST (
            .clock              (CLK_50_B2J),           // i, 使用基本clk (50MHz)
            .reset              (global_reset_w),       // i, 全域重置輸入，啟動重置流程
            .pll_powerdown      (),                     // o, 輸出給 ATX_PLL 的重置訊號
            .tx_analogreset     (tx_analogreset_w),     // o, 輸出給 PHY 發送端類比電路重置
            .tx_digitalreset    (tx_digitalreset_w),    // o, 輸出給 PHY 發送端數位電路重置
            .tx_ready           (tx_ready_w),                     // o, 通知系統：發送端已準備就緒
