            .rx_analogreset     (rx_analogreset_w),     // o, 輸出給 PHY 接收端類比電路重置
            .rx_digitalreset    (rx_digitalreset_w),    // o, 輸出給 PHY 接收端數位電路重置
            .rx_ready           (rx_ready_w),                     // o, 通知系統：接收端已準備就緒
            .rx_is_lockedtodata (rx_is_lockedtodata_w), // i, 接收 PHY 的 CDR 資料鎖定狀態
            .rx_cal_busy        (rx_cal_busy_w)         // i, 接收 PHY 接收端的校準忙碌狀態
        );


// =======================================================
// PHY
// =======================================================
wire [3:0] phy_tx_cal_busy_w, phy_rx_cal_busy_w;
assign tx_cal_busy_w = |phy_tx_cal_busy_w;
assign rx_cal_busy_w = |phy_rx_cal_busy_w;

wire [3:0] phy_rx_is_lockedtodata_w;
assign rx_is_lockedtodata_w = &phy_rx_is_lockedtodata_w;

wire [3:0] phy_tx_clkout_w, phy_rx_clkout_w;    // 除頻後的clk, 使用這個去接收 64bit 資料

reg [63:0] phy_tx_parallel_data_r[0:3], phy_tx_parallel_data_w[0:3];
reg [3:0] phy_tx_enh_data_valid_r, phy_tx_enh_data_valid_w;
reg [1:0] phy_tx_control_r[0:3], phy_tx_control_w[0:3];
