wire [63:0] phy_rx_parallel_data_w[0:3];
// wire [1:0] phy_rx_control_w[0:3];
wire [3:0] phy_rx_enh_data_valid_w;
reg [63:0] phy_rx_parallel_data_r[0:3];
// reg [7:0] phy_rx_control_r[0:3];


PHY_enhance_PCS PHY_enh (
                    .tx_analogreset          ({4{tx_analogreset_w}}),
                    .tx_digitalreset         ({4{tx_digitalreset_w}}),
                    .rx_analogreset          ({4{rx_analogreset_w}}),
                    .rx_digitalreset         ({4{rx_digitalreset_w}}),
                    .tx_cal_busy             (phy_tx_cal_busy_w),
                    .rx_cal_busy             (phy_rx_cal_busy_w),
                    .tx_serial_clk0          ({4{tx_serial_clk_w}}),    // 吃 ATX_PLL 產生的 5156.25 MHz clk 當作發送端的串行時脈
                    .rx_cdr_refclk0          (QSFPA_REFCLK_p),    // 吃 Si5340A 產生的 644.53125 MHz clk 當作 CDR 的參考時脈
                    .tx_serial_data          (QSFPA_TX_p),
                    .rx_serial_data          (QSFPA_RX_p),
