                    .rx_clkout               (phy_rx_clkout_w),
                    .tx_parallel_data        ({phy_tx_parallel_data_r[3], phy_tx_parallel_data_r[2], phy_tx_parallel_data_r[1], phy_tx_parallel_data_r[0]}),    //
                    .rx_parallel_data        ({phy_rx_parallel_data_w[3], phy_rx_parallel_data_w[2], phy_rx_parallel_data_w[1], phy_rx_parallel_data_w[0]}),    //
                    .tx_control              ({phy_tx_control_r[3], phy_tx_control_r[2], phy_tx_control_r[1], phy_tx_control_r[0]}),
