                    .rx_enh_fifo_rd_en       (4'b1111)
                );



// ===================================================================
// Tx Sequential
// ===================================================================
reg [5:0] cnt_tx_r[0:3];
integer i;
genvar j;
generate
    for (j = 0; j < 4; j = j + 1)
    begin : tx_seq
        always @(posedge phy_tx_clkout_w[j] or posedge tx_digitalreset_w)
        begin
            if (tx_digitalreset_w)
            begin
                phy_tx_parallel_data_r[j] <= 64'b0;
                phy_tx_enh_data_valid_r[j] <= 1'b0;
                cnt_tx_r[j] <= 6'b0;
                phy_tx_control_r[j] <= 2'b00;
            end
            else
            begin
                phy_tx_parallel_data_r[j] <= phy_tx_parallel_data_w[j];
                phy_tx_enh_data_valid_r[j] <= phy_tx_enh_data_valid_w[j];
                phy_tx_control_r[j] <= phy_tx_control_w[j];

                if (tx_ready_w)
                    // 精準計數：從 0 數到 32，共 33 個 Cycle 為一個循環
                    cnt_tx_r[j] <= (cnt_tx_r[j] == 6'd32) ? 6'd0 : cnt_tx_r[j] + 1;
            end
        end
    end
endgenerate


// ===================================================================
// Tx comb
// ===================================================================
always @(*)
begin
    // default
    for (i = 0; i < 4; i = i + 1)
    begin
        phy_tx_parallel_data_w[i] = phy_tx_parallel_data_r[i];
        phy_tx_control_w[i] = 2'b10;
        phy_tx_enh_data_valid_w[i] = 1'b0;
    end

    // Sending
    if (tx_digitalreset_w == 1'b0 && tx_ready_w == 1'b1)
    begin
        for (i = 0; i < 4; i = i + 1)
        begin
            if (phy_tx_enh_fifo_pfull_w[i] == 1'b1)
            begin
                phy_tx_enh_data_valid_w[i] = 1'b0;  // 暫停寫入，讓 PHY 補 Header
                phy_tx_control_w[i] = 2'b10;
                phy_tx_parallel_data_w[i] = phy_tx_parallel_data_r[i]; // 資料扣住不變，等待下個 cycle
            end
            else
            begin
                phy_tx_enh_data_valid_w[i] = 1'b1;  // 正常寫入
                phy_tx_control_w[i] = 2'b01;        // Data
                phy_tx_parallel_data_w[i] = phy_tx_parallel_data_r[i] + (i+1);
            end
        end
    end
end

// ==================================================================
// Rx Sequential
// ==================================================================
reg [26:0] cnt_ref_r, cnt_ref_w;
reg [26:0] cnt_data_r[0:3], cnt_data_w[0:3];
generate
    for (j = 0; j < 4; j = j + 1)
    begin : rx_seq
        always @(posedge phy_rx_clkout_w[j] or posedge rx_digitalreset_w)
        begin
            if (rx_digitalreset_w)
            begin
                if (j == 0)
                    cnt_ref_r <= 27'b0;
                cnt_data_r[j] <= 27'b0;
                phy_rx_parallel_data_r[j] <= 64'b0;
                // phy_rx_control_r[j] <= 8'b0;
            end
            else
            begin
                if (j == 0)
                    cnt_ref_r <= cnt_ref_r +1;
                cnt_data_r[j] <= cnt_data_w[j];
                // phy_rx_control_r[j] <= phy_rx_control_w[j];
                if (phy_rx_enh_data_valid_w[j] == 1'b1)
                    phy_rx_parallel_data_r[j] <= phy_rx_parallel_data_w[j];

            end
        end
    end
endgenerate

// ==================================================================
// Rx comb
// ==================================================================
generate
    for (j = 0; j < 4; j = j + 1)
    begin : rx_comb
        always @(*)
        begin
            // default
            cnt_data_w[j] = 0;

            // Receiving
            if (rx_digitalreset_w == 1'b0 && rx_ready_w == 1'b1)
            begin
                if (phy_rx_enh_data_valid_w[j] == 1'b1) // Data valid
                begin
                    if (phy_rx_parallel_data_w[j] == phy_rx_parallel_data_r[j] + (j+1))
                        cnt_data_w[j] = cnt_data_r[j] + 1;
                end
                else
                begin
                    // 接收 IDLE 就keep
                    cnt_data_w[j] = cnt_data_r[j];
                end
            end
        end
    end
endgenerate



assign  LED[0] = cnt_ref_r[26];
assign  LED_BRACKET[0] = cnt_data_r[0][26];
assign  LED_BRACKET[1] = cnt_data_r[1][26];
assign  LED_BRACKET[2] = cnt_data_r[2][26];
assign  LED_BRACKET[3] = cnt_data_r[3][26];
endmodule
